    "questionAr": "إذا كانت $\\omega$ أحد الجذور التكعيبية المركبة للواحد الصحيح، فما هي قيمة $x$ التي تجعل قيمة المحدد مساوية للصفر؟\n$$\\begin{vmatrix} x & \\omega & \\omega^2 \\\\ \\omega & \\omega^2 & x \\\\ \\omega^2 & x & \\omega \\end{vmatrix} = 0$$",
